from taf.internal.cloud.lcmaas.client.lcmaas.v1 import (ActionsApi, ActionValidateIn, ActionOnboardIn,
                                                        ActionInstantiateIn, ActionTerminateIn, ActionUpgradeIn,
                                                        ActionRollbackIn)


class ActionsV1(object):
    def __init__(self, api_client):
        self.actions_api_v1 = ActionsApi(api_client=api_client)

    def validate_dpp(self, dpp_name=None, dpp_group=None):
        act_validation = ActionValidateIn(dpp_name=dpp_name, dpp_group=dpp_group)
        return self.actions_api_v1.actions_validate_post(action_validate_in=act_validation)

    def onboard_container_images_to_vi(self, dpp_name=None, dpp_group=None):
        onboard_data = ActionOnboardIn(dpp_name=dpp_name, dpp_group=dpp_group)
        return self.actions_api_v1.actions_onboard_post(action_onboard_in=onboard_data)

    def instantiate_dpp(self, dpp_name=None, dpp_group=None):
        instantiate_data = ActionInstantiateIn(dpp_name=dpp_name, dpp_group=dpp_group)
        return self.actions_api_v1.actions_instantiate_post(action_instantiate_in=instantiate_data)

    def terminate_dpp(self, dpp_name=None, dpp_group=None):
        terminate_data = ActionTerminateIn(dpp_name=dpp_name, dpp_group=dpp_group)
        return self.actions_api_v1.actions_terminate_post(action_terminate_in=terminate_data)

    def upgrade_dpp(self, dpp_name=None, dpp_group=None):
        upgrade_data = ActionUpgradeIn(dpp_name=dpp_name, dpp_group=dpp_group)
        return self.actions_api_v1.actions_upgrade_post(action_upgrade_in=upgrade_data)

    def rollback_dpp(self, dpp_name=None, dpp_group=None):
        rollback_data = ActionRollbackIn(dpp_name=dpp_name, dpp_group=dpp_group)
        return self.actions_api_v1.actions_rollback_post(action_rollback_in=rollback_data)
